def gen(rng):
    def fmt(ws):
        return str(len(ws)) + '\n' + '\n'.join(ws)
    def word(alpha, lo, hi):
        return ''.join(rng.choice(alpha) for _ in range(rng.randint(lo, hi)))
    tests = [
        fmt(['a']),
        fmt(['abc', 'abc', 'abc']),
        fmt(['zz', 'zy', 'yz', 'zz']),
        fmt(['listen', 'silent', 'enlist', 'google', 'gogole', 'tinsel']),
        fmt(['b', 'a', 'c', 'a', 'b']),
        fmt(['ab', 'ba', 'a', 'aab', 'aba', 'baa', 'abb']),
    ]
    for n in (2, 4, 6, 8, 12, 20, 30):
        for alpha in ('ab', 'abc', 'abcdef'):
            tests.append(fmt([word(alpha, 1, 4) for _ in range(n)]))
    tests.append(fmt([word('abcdefghijklmnopqrstuvwxyz', 1, 15) for _ in range(3000)]))
    tests.append(fmt([word('abc', 1, 8) for _ in range(100000)]))
    tests.append(fmt([word('abcdefghijklmnopqrstuvwxyz', 6, 12) for _ in range(100000)]))
    base = [word('abcdefghijklmnopqrstuvwxyz', 15, 15) for _ in range(50)]
    ws = []
    for _ in range(100000):
        w = list(rng.choice(base))
        rng.shuffle(w)
        ws.append(''.join(w))
    tests.append(fmt(ws))
    return tests

